<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Building2, GitBranch, UsersRound, UserRoundCog, History, Plus, Pencil, Power, X, Search, ShieldCheck } from 'lucide-vue-next'
import { useGovernanceStore } from '../store'
import { roles } from '../domain'
import { organizationTypes, type Organization, type Unit, type Person, type Position, type ProcessRole } from '../directory'
const store = useGovernanceStore()
const tabs = [{ id: 'organization', name: 'Tashkilotlar', icon: Building2 }, { id: 'unit', name: 'Tarkibiy bo‘linmalar', icon: GitBranch }, { id: 'position', name: 'Lavozimlar va rollar', icon: UserRoundCog }, { id: 'person', name: 'Xodimlar', icon: UsersRound }, { id: 'assignments', name: 'Loyiha mas’ullari', icon: UserRoundCog }, { id: 'audit', name: 'O‘zgarishlar tarixi', icon: History }]
const selected = ref('organization')
const query = ref('')
const organizationFilter = ref('')
const activeFilter = ref('all')
const admin = computed(() => store.role === 'admin')
const dialog = ref<HTMLDialogElement>()
const assignmentDialog = ref<HTMLDialogElement>()
const feedback = ref(''), failure = ref(false)
const form = reactive({ id: '', code: '', name: '', type: 'agency' as Organization['type'], organizationId: '', unitId: '', positionId: '', position: '', roles: [] as ProcessRole[], active: true })
const projectId = ref(store.projects[0]?.id || '')
const selectedProject = computed(() => store.projects.find(p => p.id === projectId.value))
const processRoles = roles.filter(r => !['admin', 'council'].includes(r.id)) as { id: ProcessRole; title: string }[]
const assignment = reactive({ role: 'initiator' as ProcessRole, positionId: '', reason: '' })
const eligiblePeople = computed(() => store.directory.positions.filter(p => p.active && p.roles.includes(assignment.role) && (assignment.role !== 'initiator' || (p.organizationId === selectedProject.value?.organizationId && p.unitId === selectedProject.value?.unitId))))
const unitsForForm = computed(() => store.directory.units.filter(u => u.active && u.organizationId === form.organizationId))
const rows = computed(() => {
  const source = selected.value === 'organization' ? store.directory.organizations : selected.value === 'unit' ? store.directory.units : selected.value === 'position' ? store.directory.positions : store.directory.people
  return source.filter(item => (activeFilter.value === 'all' || item.active === (activeFilter.value === 'active')) && (!organizationFilter.value || ('organizationId' in item ? item.organizationId === organizationFilter.value : item.id === organizationFilter.value)) && `${item.name} ${'code' in item ? item.code : item.position}`.toLowerCase().includes(query.value.toLowerCase()))
})
function run(fn: () => void) { try { fn(); feedback.value = 'O‘zgarish demo rejimida saqlandi.'; failure.value = false } catch (e) { failure.value = true; feedback.value = e instanceof Error ? e.message : 'Amal bajarilmadi.' } }
function open(item?: Organization | Unit | Person | Position) {
  feedback.value = ''; failure.value = false
  Object.assign(form, { id: '', code: '', name: '', type: 'agency', organizationId: '', unitId: '', positionId: '', position: '', roles: [], active: true })
  if (item) Object.assign(form, item, { roles: 'roles' in item ? [...item.roles] : [] })
  dialog.value?.showModal()
}
function save() {
  run(() => {
    if (selected.value === 'organization') store.saveOrganization({ id: form.id, code: form.code, name: form.name, type: form.type, active: form.active })
    if (selected.value === 'unit') store.saveUnit({ id: form.id, code: form.code, name: form.name, organizationId: form.organizationId, active: form.active })
    if (selected.value === 'position') store.savePosition({ id: form.id, code: form.code, name: form.name, organizationId: form.organizationId, unitId: form.unitId, roles: [...form.roles], active: form.active })
    if (selected.value === 'person') store.savePerson({ positionId: form.positionId, id: form.id, name: form.name, organizationId: form.organizationId, unitId: form.unitId, position: form.position, roles: [...form.roles], active: form.active })
    dialog.value?.close()
  })
}
function toggle(id: string) { if (['organization', 'unit', 'person', 'position'].includes(selected.value)) run(() => store.toggleRecord(selected.value as 'organization' | 'unit' | 'person' | 'position', id)) }
function openAssignment(role: ProcessRole) { feedback.value = ''; failure.value = false; Object.assign(assignment, { role, positionId: selectedProject.value?.assignees?.[role] || '', reason: '' }); assignmentDialog.value?.showModal() }
function saveAssignment() { run(() => { store.assign(projectId.value, assignment.role, assignment.positionId, assignment.reason); assignmentDialog.value?.close() }) }
</script>
<template>
  <section class="gov-management">
    <div class="gov-council-banner"><ShieldCheck :size="29" /><div><b>Tashkilot → tarkibiy bo‘linma → lavozim → loyiha vazifasi</b><p>Yagona ma’lumotnoma. Loyihalar ID orqali bog‘lanadi; xodim almashganda hujjat shu lavozimda qoladi.</p></div></div>
    <div v-if="!admin" class="gov-warning">Ko‘rish rejimi. Tahrirlash uchun yuqoridagi «Demo rol»dan «Boshqaruv administratori · demo»ni tanlang. Bu demo vakolat, serverdagi foydalanuvchi ruxsati emas.</div>
    <div v-if="feedback && !dialog?.open && !assignmentDialog?.open" :class="['gov-feedback', { error: failure }]" role="status">{{ feedback }}<button aria-label="Xabarni yopish" @click="feedback = ''"><X :size="16" /></button></div>
    <nav class="gov-tabs" aria-label="Boshqaruv bo‘limlari"><button v-for="t in tabs" :key="t.id" :class="{ active: selected === t.id }" @click="selected = t.id; query = ''; organizationFilter = ''"><component :is="t.icon" :size="16" />{{ t.name }}</button></nav>
    <template v-if="['organization', 'unit', 'person', 'position'].includes(selected)">
      <div class="gov-toolbar"><label class="gov-search"><Search :size="17" /><input v-model="query" placeholder="Nomi, kodi yoki lavozim bo‘yicha qidiring" aria-label="Ma’lumotnomadan qidirish"></label><select v-if="selected !== 'organization'" v-model="organizationFilter" aria-label="Tashkilot filtri"><option value="">Barcha tashkilotlar</option><option v-for="o in store.directory.organizations" :key="o.id" :value="o.id">{{ o.name }}</option></select><select v-model="activeFilter" aria-label="Faollik filtri"><option value="all">Barcha yozuvlar</option><option value="active">Faol</option><option value="inactive">Nofaol</option></select><button v-if="admin" class="gov-primary" @click="open()"><Plus :size="16" />{{ selected === 'organization' ? 'Tashkilot qo‘shish' : selected === 'unit' ? 'Bo‘linma qo‘shish' : selected === 'position' ? 'Lavozim qo‘shish' : 'Xodim qo‘shish' }}</button></div>
      <section class="gov-panel gov-table-wrap"><table><thead><tr><th>{{ selected === 'person' ? 'Xodim / lavozim' : 'Nomi / kodi' }}</th><th>{{ selected === 'organization' ? 'Turi / tarkibi' : 'Tashkilot' }}</th><th>{{ selected === 'person' ? 'Bo‘linma / vazifalar' : 'Bog‘liqlik' }}</th><th>Holat</th><th v-if="admin">Amallar</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{ item.name }}</b><small>{{ 'code' in item ? item.code : item.position }}</small></td><td><template v-if="'type' in item">{{ organizationTypes.find(t => t.id === item.type)?.title }}<small>{{ store.directory.units.filter(u => u.organizationId === item.id).length }} ta bo‘linma</small></template><template v-else>{{ store.organizationName(item.organizationId) }}</template></td><td><template v-if="'roles' in item">{{ store.unitName(item.unitId) }}<small>{{ item.roles.map(r => roles.find(role => role.id === r)?.title).join(' · ') }}</small></template><template v-else-if="'organizationId' in item">{{ store.directory.people.filter(p => p.unitId === item.id).length }} ta xodim</template><template v-else>{{ store.directory.people.filter(p => p.organizationId === item.id).length }} ta xodim</template></td><td><span class="gov-status" :data-state="item.active ? 'active' : 'returned'">{{ item.active ? 'Faol' : 'Nofaol' }}</span></td><td v-if="admin"><div class="gov-directory-actions"><button :aria-label="`${item.name} tahrirlash`" @click="open(item)"><Pencil :size="15" /> Tahrirlash</button><button :aria-label="`${item.name} ${item.active ? 'nofaol qilish' : 'faollashtirish'}`" @click="toggle(item.id)"><Power :size="15" />{{ item.active ? 'Nofaol qilish' : 'Faollashtirish' }}</button></div></td></tr><tr v-if="!rows.length"><td colspan="5" class="gov-empty">Tanlangan filtrda yozuv topilmadi.</td></tr></tbody></table></section>
    </template>
    <section v-else-if="selected === 'assignments'" class="gov-panel gov-pad"><div class="gov-panel-title"><h3>Loyiha bo‘yicha mas’ullar</h3><select v-model="projectId" aria-label="Mas’ullar uchun loyiha"><option v-for="p in store.projects" :key="p.id" :value="p.id">{{ p.id }} · {{ p.title }}</option></select></div><p class="gov-muted">Vazifa lavozimga biriktiriladi. Shu lavozimdagi faol xodim hujjatni davom ettiradi; avvalgi ijrochining harakatlari tarixda qoladi. Server RBAC integratsiyasi keyingi bosqichda.</p><div v-if="selectedProject" class="gov-assignment-grid"><article v-for="r in processRoles" :key="r.id"><UserRoundCog :size="21" /><small>{{ r.title }}</small><b>{{ store.assignedName(selectedProject, r.id) }}</b><span>{{ store.directory.positions.find(p => p.id === selectedProject?.assignees?.[r.id])?.code || 'Mas’ul biriktirilmagan' }}</span><button v-if="admin" @click="openAssignment(r.id)"><Pencil :size="14" /> Mas’ulni biriktirish</button></article></div></section>
    <section v-else class="gov-panel gov-pad"><h3>Boshqaruv o‘zgarishlari tarixi</h3><div v-for="event in store.managementAudit" :key="event.id" class="gov-history"><History :size="18" /><div><b>{{ event.action }}</b><p>{{ event.details }}</p><small>{{ new Date(event.at).toLocaleString('uz-UZ', { timeZone: 'Asia/Tashkent' }) }} · Boshqaruv administratori</small></div></div><p v-if="!store.managementAudit.length" class="gov-empty">Hali boshqaruv o‘zgarishi qayd etilmagan.</p></section>
    <dialog ref="dialog" class="gov-dialog"><form @submit.prevent="save"><header><h2>{{ form.id ? 'Ma’lumotni tahrirlash' : 'Yangi yozuv' }}</h2><button type="button" aria-label="Boshqaruv formasini yopish" @click="dialog?.close()"><X :size="20" /></button></header><label v-if="selected !== 'organization'" class="gov-field">Tashkilot<select v-model="form.organizationId" required @change="form.unitId = ''"><option value="">Tanlang</option><option v-for="o in store.directory.organizations.filter(o => o.active)" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label v-if="['person', 'position'].includes(selected)" class="gov-field">Tarkibiy bo‘linma<select v-model="form.unitId" required><option value="">Tanlang</option><option v-for="u in unitsForForm" :key="u.id" :value="u.id">{{ u.name }}</option></select></label><label class="gov-field">{{ selected === 'person' ? 'F.I.Sh.' : 'Nomi' }}<input v-model="form.name" required></label><label v-if="selected !== 'person'" class="gov-field">Kodi<input v-model="form.code" required></label><label v-if="selected === 'organization'" class="gov-field">Tashkilot turi<select v-model="form.type"><option v-for="t in organizationTypes" :key="t.id" :value="t.id">{{ t.title }}</option></select></label><label v-if="selected === 'person'" class="gov-field">Lavozimi<select v-model="form.positionId" required><option value="">Tanlang</option><option v-for="p in store.directory.positions.filter(p => p.active && p.unitId === form.unitId)" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><template v-if="selected === 'position'"><h4>Jarayondagi vazifalar</h4><label v-for="r in processRoles" :key="r.id" class="gov-check"><input v-model="form.roles" type="checkbox" :value="r.id">{{ r.title }}</label></template><p v-if="failure && feedback" class="gov-warning" role="alert">{{ feedback }}</p><footer><button type="button" @click="dialog?.close()">Bekor qilish</button><button class="gov-primary" type="submit">Saqlash</button></footer></form></dialog>
    <dialog ref="assignmentDialog" class="gov-dialog"><form @submit.prevent="saveAssignment"><header><h2>Mas’ulni biriktirish</h2><button type="button" aria-label="Biriktirish formasini yopish" @click="assignmentDialog?.close()"><X :size="20" /></button></header><p class="gov-muted">{{ processRoles.find(r => r.id === assignment.role)?.title }} · {{ selectedProject?.title }}</p><label class="gov-field">Mas’ul lavozim<select v-model="assignment.positionId" required><option value="">Tanlang</option><option v-for="p in eligiblePeople" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="gov-field">Biriktirish / almashtirish sababi<textarea v-model="assignment.reason" required rows="3" /></label><p v-if="!eligiblePeople.length" class="gov-warning">Mos faol lavozim yo‘q. Lavozimlar ma’lumotnomasiga mos rol bilan lavozim kiriting.</p><p v-if="failure && feedback" class="gov-warning" role="alert">{{ feedback }}</p><footer><button type="button" @click="assignmentDialog?.close()">Bekor qilish</button><button type="submit" class="gov-primary">Biriktirishni saqlash</button></footer></form></dialog>
  </section>
</template>
